/* eslint-disable */
import React, { useEffect, useState } from "react";
import { ccc } from "@ckb-ccc/connector-react";
import { truncateAddress } from "../utils/stringUtils";

const ConnectWallet: React.FC = () => {
  const { open, disconnect } = ccc.useCcc();
  const signer = ccc.useSigner();

  const [address, setAddress] = useState<string>("");

  useEffect(() => {
    if (!signer) {
      setAddress("");
      return;
    }

    (async () => {
      const addr = await signer.getRecommendedAddress();
      setAddress(addr);
    })();
  }, [signer]);

  return (
    <div className="p-4 border rounded">
      {!signer ? (
        <button onClick={open}>
          Connect Wallet
        </button>
      ) : (
        <>
          <p>Connected</p>
          <p>Address: {truncateAddress(address)}</p>
          <button onClick={disconnect}>
            Disconnect
          </button>
        </>
      )}


  <div className="p-4 border rounded mt-4">
    <h3>On-Chain Counter</h3>

    {/* 1️⃣ Show counter value */}
    {counter !== null && (
      <p>Counter Value: {counter}</p>
    )}

    {/* 2️⃣ Create button (only once) */}
    {counter === null && (
      <button disabled={!signer} onClick={createCounter}>
        Create Counter Cell
      </button>
    )}

    {/* 3️⃣ AFTER creation → show increment */}
    {counter !== null && (
      <div style={{ marginTop: "10px" }}>
        <button onClick={incrementCounter}>
          Increment
        </button>

        <button onClick={readCounter} style={{ marginLeft: "8px" }}>
          Read From Chain
        </button>
      </div>
    )}

    {/* 4️⃣ Debug info */}
    {txHash && (
      <>
        <p style={{ wordBreak: "break-all" }}>
          Tx Hash: {txHash}
        </p>
        <p>
          OutPoint: {outPoint?.tx_hash} : {outPoint?.index}
        </p>
      </>
    )}
  </div>

    </div>
  );
};

export default ConnectWallet;
